  "DELETE /v1/brands/{id}/linkedin-page": {
    "service": "brand-service",
    "method": "DELETE",
    "path": "/orgs/brands/{brandId}/linkedin-page",
    "responses": {
      "200": {
        "description": "The stored answer after clearing",
        "schema": {
          "type": "object",
          "properties": {
            "brandId": {
              "type": "string",
              "format": "uuid"
            },
            "status": {
              "type": "string",
              "enum": [
                "not_computed",
                "found",
                "not_found"
              ]
            },
            "linkedinUrl": {
              "type": "string",
              "nullable": true,
              "description": "`https://www.linkedin.com/company/<slug>/`, or null"
            },
            "discoveredAt": {
              "type": "string",
              "nullable": true
            },
            "noneFoundReason": {
              "type": "string",
              "nullable": true,
              "description": "Why a `not_found` is not found, naming every source asked (site pages read, what Apollo answered). null otherwise."
            },
            "provenance": {
              "type": "object",
              "nullable": true,
              "properties": {
                "method": {
                  "type": "string",
                  "enum": [
                    "brand_website_link",
                    "apollo_company_lookup",
                    "set_by_user"
                  ],
                  "description": "`set_by_user` when a person set the page; `apollo_company_lookup` when Apollo found it; `brand_website_link` otherwise"
                },
                "source": {
                  "type": "string",
                  "nullable": true,
                  "enum": [
                    "brand_website",
                    "apollo",
                    "user",
                    null
                  ],
                  "description": "Who found it (`user` = set by a person); set when found"
                },
                "setBy": {
                  "type": "object",
                  "nullable": true,
                  "properties": {
                    "userId": {
                      "type": "string",
                      "nullable": true,
                      "description": "Internal user id of the person who set it (null when the caller sent none)"
                    },
                    "orgId": {
                      "type": "string",
                      "nullable": true,
                      "description": "Internal org id the person set it from"
                    },
                    "at": {
                      "type": "string",
                      "nullable": true,
                      "description": "When it was set"
                    }
                  },
                  "required": [
                    "userId",
                    "orgId",
                    "at"
                  ],
                  "description": "Who set the page and when; null unless `source` is `user`"
                },
                "foundOnUrl": {
                  "type": "string",
                  "nullable": true,
                  "description": "The page of the brand site the link was read on (source brand_website only)"
                },
                "pagesRead": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  },
                  "description": "Every page of the brand site that was read"
                },
                "runId": {
                  "type": "string",
                  "nullable": true,
                  "description": "brand-service run that paid for a scrape; null when every read was free"
                },
                "apollo": {
                  "type": "object",
                  "properties": {
                    "asked": {
                      "type": "boolean",
                      "description": "false = decided by the site reads before Apollo was asked"
                    },
                    "askedAt": {
                      "type": "string",
                      "nullable": true
                    },
                    "outcome": {
                      "type": "string",
                      "nullable": true,
                      "enum": [
                        "linkedin_page",
                        "no_company",
                        "no_linkedin_url",
                        "other_domain",
                        "not_company_page",
                        null
                      ],
                      "description": "Apollo company record by the brand domain: kept only when it is for that exact domain and names a company page"
                    },
                    "linkedinUrl": {
                      "type": "string",
                      "nullable": true,
                      "description": "Apollo `linkedin_url`, verbatim"
                    }
                  },
                  "required": [
                    "asked",
                    "askedAt",
                    "outcome",
                    "linkedinUrl"
                  ],
                  "description": "Apollo company lookup (apollo-service, platform-billed, cached there)"
                }
              },
              "required": [
                "method",
                "source",
                "setBy",
                "foundOnUrl",
                "pagesRead",
                "runId",
                "apollo"
              ]
            }
          },
          "required": [
            "brandId",
            "status",
            "linkedinUrl",
            "discoveredAt",
            "noneFoundReason",
            "provenance"
          ]
        }
      }
    }
  },
