  "GET /v1/brands/{brandId}/conversions": {
    "service": "lead-service",
    "method": "GET",
    "path": "/orgs/brands/{brandId}/conversions",
    "responses": {
      "200": {
        "description": "Conversions",
        "schema": {
          "type": "object",
          "properties": {
            "brandId": {
              "type": "string"
            },
            "total": {
              "type": "integer"
            },
            "conversions": {
              "type": "array",
              "items": {
                "type": "object",
                "properties": {
                  "id": {
                    "type": "string",
                    "description": "The conversion id: what the withdraw route takes."
                  },
                  "event": {
                    "type": "string",
                    "description": "signup, meeting_booked, form_submission, sale, positive_reply (CRM), ..."
                  },
                  "source": {
                    "type": "string",
                    "description": "tracker (your website tag), crm, manual (a person's statement), reply (read off a prospect's reply)."
                  },
                  "email": {
                    "type": "string",
                    "nullable": true
                  },
                  "firstName": {
                    "type": "string",
                    "nullable": true
                  },
                  "lastName": {
                    "type": "string",
                    "nullable": true
                  },
                  "receivedAt": {
                    "type": "string",
                    "nullable": true
                  },
                  "valueCents": {
                    "type": "integer",
                    "nullable": true
                  },
                  "leadId": {
                    "type": "string",
                    "nullable": true,
                    "description": "The lead it is attributed to (or the candidate held for review)."
                  },
                  "matchMethod": {
                    "type": "string",
                    "nullable": true
                  },
                  "matchConfidence": {
                    "type": "string"
                  },
                  "attributionStatus": {
                    "type": "string",
                    "description": "attributed | needs_review | unmatched. A name-only match is needs_review: never counted."
                  },
                  "counted": {
                    "type": "boolean",
                    "description": "Read by the outcome counts: attributed and not withdrawn."
                  },
                  "withdrawn": {
                    "type": "object",
                    "nullable": true,
                    "properties": {
                      "at": {
                        "type": "string"
                      },
                      "byUserId": {
                        "type": "string",
                        "nullable": true
                      },
                      "reason": {
                        "type": "string",
                        "nullable": true,
                        "description": "wrong_attribution (a person, this route), staff_identity (sent by a staff address), not_a_person (lead marked), null (older withdrawals)."
                      },
                      "note": {
                        "type": "string",
                        "nullable": true
                      }
                    },
                    "required": [
                      "at",
                      "byUserId",
                      "reason",
                      "note"
                    ]
                  }
                },
                "required": [
                  "id",
                  "event",
                  "source",
                  "email",
                  "firstName",
                  "lastName",
                  "receivedAt",
                  "valueCents",
                  "leadId",
                  "matchMethod",
                  "matchConfidence",
                  "attributionStatus",
                  "counted",
                  "withdrawn"
                ]
              }
            }
          },
          "required": [
            "brandId",
            "total",
            "conversions"
          ]
        }
      }
    }
  },
