  "GET /v1/email-sequences": {
    "service": "instantly-service",
    "method": "GET",
    "path": "/orgs/email-sequences",
    "responses": {
      "200": {
        "description": "One page of sequences (possibly empty)",
        "schema": {
          "type": "object",
          "properties": {
            "brandId": {
              "type": "string"
            },
            "count": {
              "type": "integer",
              "description": "Sequences on THIS page"
            },
            "sequences": {
              "type": "array",
              "items": {
                "type": "object",
                "properties": {
                  "leadId": {
                    "type": "string",
                    "nullable": true,
                    "description": "The lead id, the same `leadId` content-generation-service carries on the generated email"
                  },
                  "leadEmail": {
                    "type": "string"
                  },
                  "campaignId": {
                    "type": "string",
                    "nullable": true,
                    "description": "The campaign this sequence belongs to"
                  },
                  "steps": {
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "step": {
                          "type": "integer",
                          "description": "1-based position in the sequence. Step 1 is the first email."
                        },
                        "kind": {
                          "type": "string",
                          "enum": [
                            "first_email",
                            "follow_up"
                          ]
                        },
                        "status": {
                          "type": "string",
                          "enum": [
                            "sent",
                            "bounced",
                            "queued",
                            "stopped"
                          ],
                          "description": "`sent`: it went out (see `sentAt`). `bounced`: it went out and the receiving server refused it (see `bouncedAt`); it was NOT delivered. `queued`: not sent yet, it goes out in the prospect's business hours. `stopped`: it will not go out (the prospect replied, bounced, opted out or booked, or the sequence was stopped)."
                        },
                        "sentAt": {
                          "type": "string",
                          "nullable": true,
                          "description": "When it went out (ISO 8601 UTC). Null unless `sent` or `bounced`."
                        },
                        "bouncedAt": {
                          "type": "string",
                          "nullable": true,
                          "description": "When the receiving server refused it (ISO 8601 UTC). Null unless `bounced`."
                        }
                      },
                      "required": [
                        "step",
                        "kind",
                        "status",
                        "sentAt",
                        "bouncedAt"
                      ]
                    },
                    "description": "Ordered by `step`"
                  }
                },
                "required": [
                  "leadId",
                  "leadEmail",
                  "campaignId",
                  "steps"
                ]
              }
            },
            "nextCursor": {
              "type": "string",
              "nullable": true,
              "description": "Pass as `cursor` for the next page. Null = this was the last page."
            }
          },
          "required": [
            "brandId",
            "count",
            "sequences",
            "nextCursor"
          ]
        }
      }
    }
  },
