  "GET /v1/orgs/contacts": {
    "service": "crm-service",
    "method": "GET",
    "path": "/orgs/contacts",
    "responses": {
      "200": {
        "description": "Contacts",
        "schema": {
          "type": "object",
          "properties": {
            "contacts": {
              "type": "array",
              "items": {
                "type": "object",
                "properties": {
                  "id": {
                    "type": "string",
                    "format": "uuid"
                  },
                  "orgId": {
                    "type": "string",
                    "format": "uuid"
                  },
                  "brandId": {
                    "type": "string",
                    "format": "uuid"
                  },
                  "primaryEmail": {
                    "type": "string",
                    "nullable": true
                  },
                  "phoneE164": {
                    "type": "string",
                    "nullable": true
                  },
                  "fullName": {
                    "type": "string",
                    "nullable": true
                  },
                  "firstName": {
                    "type": "string",
                    "nullable": true
                  },
                  "lastName": {
                    "type": "string",
                    "nullable": true
                  },
                  "rawAttributes": {
                    "type": "object",
                    "additionalProperties": {
                      "type": "string"
                    }
                  },
                  "consentStatus": {
                    "type": "string"
                  },
                  "unsubscribed": {
                    "type": "boolean"
                  },
                  "source": {
                    "type": "string",
                    "enum": [
                      "csv",
                      "matrix",
                      "gohighlevel"
                    ],
                    "description": "Which source this contact came from. Only 'csv' contacts are sendable. A 'matrix' contact wrote in first and is already in conversation; a 'gohighlevel' contact is the client's own person, mirrored from their CRM. Neither ever reaches serve-next."
                  },
                  "channel": {
                    "type": "string",
                    "nullable": true,
                    "enum": [
                      "whatsapp",
                      "telegram",
                      "discord",
                      "linkedin",
                      null
                    ],
                    "description": "Matrix contacts only. Null for CSV contacts."
                  },
                  "channelHandle": {
                    "type": "string",
                    "nullable": true,
                    "description": "Matrix contacts only: the counterpart's bridged Matrix user id."
                  },
                  "sourceUploadId": {
                    "type": "string",
                    "nullable": true,
                    "format": "uuid"
                  },
                  "sourceRowId": {
                    "type": "string",
                    "nullable": true,
                    "format": "uuid"
                  },
                  "lastRebuiltAt": {
                    "type": "string"
                  },
                  "companyName": {
                    "type": "string",
                    "nullable": true,
                    "description": "The company the person works for, as stated (CSV column, CRM, or added one by one)."
                  },
                  "companyDomain": {
                    "type": "string",
                    "nullable": true,
                    "description": "The company's bare web domain (ntt.com)."
                  },
                  "jobTitle": {
                    "type": "string",
                    "nullable": true
                  },
                  "linkedinUrl": {
                    "type": "string",
                    "nullable": true,
                    "description": "The person's LinkedIn profile, canonical (https://www.linkedin.com/in/<slug>)."
                  },
                  "note": {
                    "type": "string",
                    "nullable": true,
                    "description": "The client's own words about the person (contacts added one by one), for the email writer."
                  },
                  "emailStatus": {
                    "type": "string",
                    "enum": [
                      "known",
                      "unknown",
                      "not_found"
                    ],
                    "description": "known = the contact holds an email (sendable like any CSV contact); unknown = not known yet: serve-next with includeEmailUnknown hands it out for the email to be looked up; not_found = a lookup found none (never handed out again)."
                  }
                },
                "required": [
                  "id",
                  "orgId",
                  "brandId",
                  "primaryEmail",
                  "phoneE164",
                  "fullName",
                  "firstName",
                  "lastName",
                  "rawAttributes",
                  "consentStatus",
                  "unsubscribed",
                  "source",
                  "channel",
                  "channelHandle",
                  "sourceUploadId",
                  "sourceRowId",
                  "lastRebuiltAt"
                ]
              }
            }
          },
          "required": [
            "contacts"
          ]
        }
      }
    }
  },
