  "GET /v1/orgs/opportunities": {
    "service": "journalists-quotes-service",
    "method": "GET",
    "path": "/orgs/opportunities",
    "responses": {
      "200": {
        "description": "All scored opportunities for the brand-set (no relevance floor), sorted by score desc",
        "schema": {
          "type": "object",
          "properties": {
            "status": {
              "type": "string",
              "enum": [
                "ok"
              ]
            },
            "opportunities": {
              "type": "array",
              "items": {
                "allOf": [
                  {
                    "type": "object",
                    "properties": {
                      "opportunityId": {
                        "type": "string",
                        "format": "uuid"
                      },
                      "provider": {
                        "type": "string"
                      },
                      "ingestionChannel": {
                        "type": "string"
                      },
                      "featuredQuestionId": {
                        "type": "integer",
                        "nullable": true
                      },
                      "mediaOutlet": {
                        "type": "string",
                        "nullable": true
                      },
                      "journalistName": {
                        "type": "string",
                        "nullable": true
                      },
                      "opportunityText": {
                        "type": "string"
                      },
                      "deadline": {
                        "type": "string",
                        "nullable": true
                      },
                      "pitchUrl": {
                        "type": "string",
                        "nullable": true
                      },
                      "pitchEmail": {
                        "type": "string",
                        "nullable": true
                      },
                      "category": {
                        "type": "string",
                        "nullable": true
                      },
                      "score": {
                        "type": "number"
                      },
                      "whyRelevant": {
                        "type": "string",
                        "nullable": true
                      }
                    },
                    "required": [
                      "opportunityId",
                      "provider",
                      "ingestionChannel",
                      "featuredQuestionId",
                      "mediaOutlet",
                      "journalistName",
                      "opportunityText",
                      "deadline",
                      "pitchUrl",
                      "pitchEmail",
                      "category",
                      "score",
                      "whyRelevant"
                    ]
                  },
                  {
                    "type": "object",
                    "properties": {
                      "pitchStatus": {
                        "type": "string",
                        "nullable": true,
                        "enum": [
                          "drafted",
                          "submitted",
                          "selected",
                          "published",
                          "not_selected",
                          "error",
                          "length_violation",
                          "template_missing",
                          "brand_missing_fields",
                          "insufficient_credits",
                          "question_not_found",
                          null
                        ]
                      }
                    },
                    "required": [
                      "pitchStatus"
                    ]
                  }
                ]
              }
            },
            "total": {
              "type": "integer"
            },
            "brandIds": {
              "type": "array",
              "items": {
                "type": "string",
                "format": "uuid"
              }
            }
          },
          "required": [
            "status",
            "opportunities",
            "total",
            "brandIds"
          ]
        }
      }
    }
  },
