  "POST /v1/brands/{id}/conversion-token/rotate": {
    "service": "lead-service",
    "method": "POST",
    "path": "/orgs/brands/{brandId}/conversion-token/rotate",
    "responses": {
      "200": {
        "description": "The new conversion token and ingest URL",
        "schema": {
          "type": "object",
          "properties": {
            "token": {
              "type": "string",
              "description": "Publishable write-key for this brand. Returned in FULL (it is embedded in a client-side pixel, so not a secret). Can only WRITE conversion events for its one brand.",
              "example": "pk_conv_9f8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c"
            },
            "ingestUrl": {
              "type": "string",
              "description": "Full public URL a third party hits for POST /public/conversions.",
              "example": "https://api.distribute.you/public/conversions"
            },
            "status": {
              "type": "string",
              "enum": [
                "not_set_up",
                "live_waiting",
                "live"
              ],
              "description": "Tracker liveness, DERIVED from received signals (never self-attested). not_set_up — nothing received yet; live_waiting — a ping proves the tag is alive but no real conversion yet; live — at least one real conversion received.",
              "example": "live_waiting"
            },
            "lastEventAt": {
              "type": "string",
              "nullable": true,
              "description": "ISO-8601 timestamp of the last REAL conversion event (signup/meeting_booked/form_submission/sale), or null.",
              "example": "2026-07-06T12:00:00.000Z"
            },
            "lastPingAt": {
              "type": "string",
              "nullable": true,
              "description": "ISO-8601 timestamp of the last liveness ping, or null.",
              "example": "2026-07-06T11:59:00.000Z"
            },
            "eventTypesSeen": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "Distinct REAL conversion event types actually received. Always EXCLUDES \"ping\".",
              "example": [
                "signup"
              ]
            }
          },
          "required": [
            "token",
            "ingestUrl",
            "status",
            "lastEventAt",
            "lastPingAt",
            "eventTypesSeen"
          ],
          "description": "The brand's publishable conversion write-key, the public ingest URL, and a derived liveness overlay (status + last event/ping timestamps + event types seen)."
        }
      }
    }
  },
