  "POST /v1/orgs/{orgId}/member-invitations": {
    "service": "client-service",
    "method": "POST",
    "path": "/internal/orgs/{orgId}/member-invitations",
    "responses": {
      "200": {
        "description": "A pending invitation for this email already existed and is returned",
        "schema": {
          "type": "object",
          "properties": {
            "invitation": {
              "type": "object",
              "properties": {
                "id": {
                  "type": "string"
                },
                "email": {
                  "type": "string"
                },
                "role": {
                  "type": "string",
                  "description": "Always `org:admin`: one role per team (same as the dashboard's invite form)."
                },
                "status": {
                  "type": "string",
                  "description": "`pending` while it can be accepted; `revoked` in the revoke response."
                },
                "inviteUrl": {
                  "type": "string",
                  "nullable": true,
                  "description": "The link the invitee opens to join (the same one the identity provider emails them), for the inviter to forward by hand. It lands on the dashboard's /invite page, which signs the person in or up inside THIS org. Never null on a creation response."
                },
                "createdAt": {
                  "type": "string"
                },
                "expiresAt": {
                  "type": "string"
                }
              },
              "required": [
                "id",
                "email",
                "role",
                "status",
                "inviteUrl",
                "createdAt",
                "expiresAt"
              ]
            },
            "created": {
              "type": "boolean",
              "enum": [
                false
              ]
            }
          },
          "required": [
            "invitation",
            "created"
          ]
        }
      },
      "201": {
        "description": "Invitation created and emailed",
        "schema": {
          "type": "object",
          "properties": {
            "invitation": {
              "type": "object",
              "properties": {
                "id": {
                  "type": "string"
                },
                "email": {
                  "type": "string"
                },
                "role": {
                  "type": "string",
                  "description": "Always `org:admin`: one role per team (same as the dashboard's invite form)."
                },
                "status": {
                  "type": "string",
                  "description": "`pending` while it can be accepted; `revoked` in the revoke response."
                },
                "inviteUrl": {
                  "type": "string",
                  "nullable": true,
                  "description": "The link the invitee opens to join (the same one the identity provider emails them), for the inviter to forward by hand. It lands on the dashboard's /invite page, which signs the person in or up inside THIS org. Never null on a creation response."
                },
                "createdAt": {
                  "type": "string"
                },
                "expiresAt": {
                  "type": "string"
                }
              },
              "required": [
                "id",
                "email",
                "role",
                "status",
                "inviteUrl",
                "createdAt",
                "expiresAt"
              ]
            },
            "created": {
              "type": "boolean",
              "enum": [
                true
              ]
            }
          },
          "required": [
            "invitation",
            "created"
          ]
        }
      }
    }
  },
