  "POST /v1/orgs/gohighlevel/connections": {
    "service": "crm-service",
    "method": "POST",
    "path": "/orgs/gohighlevel/connections",
    "responses": {
      "200": {
        "description": "Connection",
        "schema": {
          "type": "object",
          "properties": {
            "connection": {
              "type": "object",
              "properties": {
                "id": {
                  "type": "string",
                  "format": "uuid"
                },
                "brandId": {
                  "type": "string",
                  "format": "uuid"
                },
                "locationId": {
                  "type": "string",
                  "description": "The GoHighLevel sub-account ('location') id this connection mirrors. Supplied by the customer: a Private Integration Token is opaque and GoHighLevel publishes no way to read the target sub-account out of it."
                },
                "status": {
                  "type": "string",
                  "enum": [
                    "active",
                    "paused",
                    "error"
                  ]
                },
                "synced": {
                  "type": "boolean",
                  "description": "True once a sync has completed."
                },
                "lastSyncedAt": {
                  "type": "string",
                  "nullable": true
                },
                "lastError": {
                  "type": "string",
                  "nullable": true,
                  "description": "Why the last sync failed, verbatim. Null when healthy."
                },
                "lastRunId": {
                  "type": "string",
                  "nullable": true
                },
                "createdAt": {
                  "type": "string"
                },
                "booking": {
                  "type": "object",
                  "properties": {
                    "canBook": {
                      "type": "boolean",
                      "nullable": true,
                      "description": "True = the token holds the write scopes booking needs; false = it does not (show 'Reconnect with write access'); null = not known yet / GoHighLevel did not say."
                    },
                    "access": {
                      "type": "string",
                      "enum": [
                        "granted",
                        "missing",
                        "unknown",
                        "unchecked"
                      ]
                    },
                    "checkedAt": {
                      "type": "string",
                      "nullable": true
                    },
                    "vendorError": {
                      "type": "string",
                      "nullable": true,
                      "description": "GoHighLevel's own words when it refused."
                    },
                    "requiredScopes": {
                      "type": "array",
                      "items": {
                        "type": "string"
                      },
                      "description": "The Private Integration Token scopes booking needs (contacts.write, calendars/events.write)."
                    }
                  },
                  "required": [
                    "canBook",
                    "access",
                    "checkedAt",
                    "vendorError",
                    "requiredScopes"
                  ],
                  "description": "Can this connection book meetings for prospects (AUTO-BOOK-1103)."
                }
              },
              "required": [
                "id",
                "brandId",
                "locationId",
                "status",
                "synced",
                "lastSyncedAt",
                "lastError",
                "lastRunId",
                "createdAt",
                "booking"
              ]
            }
          },
          "required": [
            "connection"
          ]
        }
      }
    }
  },
