                    "provider",
                    "ingestionChannel",
                    "featuredQuestionId",
                    "mediaOutlet",
                    "journalistName",
                    "opportunityText",
                    "deadline",
                    "pitchUrl",
                    "pitchEmail",
                    "category",
                    "score",
                    "whyRelevant"
