  "POST /v1/replies": {
    "service": "instantly-service",
    "method": "POST",
    "path": "/orgs/replies",
    "responses": {
      "200": {
        "description": "The reply was sent into the lead's existing thread",
        "schema": {
          "type": "object",
          "properties": {
            "success": {
              "type": "boolean",
              "enum": [
                true
              ]
            },
            "status": {
              "type": "string",
              "enum": [
                "sent"
              ]
            },
            "reply": {
              "type": "object",
              "properties": {
                "transport": {
                  "type": "string",
                  "enum": [
                    "instantly",
                    "smtp"
                  ],
                  "description": "Which pipe carried the reply — the one that carried the outreach"
                },
                "instantlyCampaignId": {
                  "type": "string"
                },
                "leadEmail": {
                  "type": "string"
                },
                "accountEmail": {
                  "type": "string",
                  "description": "The mailbox that answered. Resolved by this service, never supplied by the caller."
                },
                "from": {
                  "type": "string",
                  "description": "The From header as the prospect sees it, persona included"
                },
                "subject": {
                  "type": "string",
                  "description": "The conversation's own subject under `Re:`"
                },
                "cc": {
                  "type": "string",
                  "description": "The agency inbox this reply was CC'd to — VISIBLE to the prospect, so a reply-all reaches a human. Never a BCC."
                },
                "messageId": {
                  "type": "string",
                  "description": "Instantly's email id, or the RFC 5322 Message-Id we sent"
                },
                "inReplyTo": {
                  "type": "string",
                  "description": "The prospect message this reply threads onto"
                },
                "attachments": {
                  "type": "array",
                  "items": {
                    "type": "object",
                    "properties": {
                      "documentId": {
                        "type": "string",
                        "description": "The brand-service offer document id"
                      },
                      "filename": {
                        "type": "string"
                      },
                      "contentType": {
                        "type": "string"
                      },
                      "sizeBytes": {
                        "type": "integer"
                      },
                      "md5": {
                        "type": "string",
                        "description": "Hex md5 of the exact bytes attached"
                      }
                    },
                    "required": [
                      "documentId",
                      "filename",
                      "contentType",
                      "sizeBytes",
                      "md5"
                    ]
                  },
                  "description": "The files this reply carried. Absent when it carried none."
                }
              },
              "required": [
                "transport",
                "instantlyCampaignId",
                "leadEmail",
                "accountEmail",
                "from",
                "subject",
                "cc",
                "messageId",
                "inReplyTo"
              ]
            }
          },
          "required": [
            "success",
            "status",
            "reply"
          ]
        }
      }
    }
  },
